"""Analyze run_*.csv files generated by perf stat -x , (individual runs)."""
import csv
import statistics
from pathlib import Path

folder = Path(__file__).resolve().parents[1] / 'results' / 'individual_runs'
cycles, instructions, ipc_values = [], [], []
for path in sorted(folder.glob('run_*.csv')):
    events = {}
    with path.open(newline='') as file:
        for row in csv.reader(file):
            if len(row) < 3 or row[0].startswith('#'):
                continue
            try:
                events[row[2].strip()] = float(row[0])
            except ValueError:
                continue
    if events.get('cycles', 0) > 0 and 'instructions' in events:
        c, ins = events['cycles'], events['instructions']
        cycles.append(c)
        instructions.append(ins)
        ipc_values.append(ins / c)

print('AMD Zen 3: Individual Run Analysis')
print('---------------------------------------')
if len(cycles) < 2:
    raise SystemExit('Need at least 2 raw CSV files in results/individual_runs.')
print(f'Valid runs: {len(cycles)}')
for name, values in [('Cycles', cycles), ('Instructions', instructions), ('IPC', ipc_values)]:
    mean, stdev = statistics.mean(values), statistics.stdev(values)
    print(f'\n{name}')
    print(f'  Mean: {mean:,.4f}')
    print(f'  Standard deviation: {stdev:,.4f}')
    print(f'  Coefficient of variation: {100 * stdev / mean if mean else 0:.2f}%')
    print(f'  Minimum: {min(values):,.4f}')
    print(f'  Maximum: {max(values):,.4f}')
